window.bookSummaryJSON = "<p><i>This book bundle contains books 1, 2, and 3 of the Nocturne Falls series.</i></p> <p><b>Welcome to Nocturne Falls, the town that celebrates Halloween 365 days a year.</b></p> <p><b>The tourists think it's all a show: the vampires, the werewolves, the witches, the occasional gargoyle flying through the sky. But the supernaturals populating the town know better.</b></p> <p><b>Living in Nocturne Falls means being yourself. Fangs, fur, and all.</b></p>"; 
